def _D_TL(pts, W=600, H=168):
    """A timeline, years left to right at equal spacing, with a break mark where the years jump. pts: (year, line 1, line 2, line 3, step)."""
    n = len(pts)
    X = [66 + i * (W - 132) / (n - 1) for i in range(n)]
    y = 58
    p = [f'<line x1="12" y1="{y}" x2="{W - 18}" y2="{y}" stroke="#1b2d55" stroke-width="3"/><polygon points="{W - 4},{y} {W - 19},{y - 7} {W - 19},{y + 7}" fill="#1b2d55"/>']
    for i in range(n - 1):
        if pts[i + 1][0] - pts[i][0] > 50:
            xm = (X[i] + X[i + 1]) / 2
            p.append(f'<path d="M{xm - 11:.1f} {y + 11}l8 -22M{xm + 2:.1f} {y + 11}l8 -22" stroke="#8a93aa" stroke-width="3"/>')
    for (yr, a, b, c, s), x in zip(pts, X):
        g = (f'<circle cx="{x:.1f}" cy="{y}" r="9" fill="#ff6a4d" stroke="#fff" stroke-width="3"/>'
             f'<text x="{x:.1f}" y="{y - 18}" font-size="22" font-weight="800" fill="#1b2d55" text-anchor="middle">{yr}</text>'
             f'<text x="{x:.1f}" y="{y + 36}" font-size="17" font-weight="800" fill="#2a3858" text-anchor="middle" direction="rtl">{a}</text>'
             f'<text x="{x:.1f}" y="{y + 59}" font-size="17" fill="#2a3858" text-anchor="middle" direction="rtl">{b}</text>'
             f'<text x="{x:.1f}" y="{y + 81}" font-size="17" fill="#2a3858" text-anchor="middle" direction="rtl">{c}</text>')
        p.append(f'<g class="st" data-n="{s * 10}">{g}</g>')
    return f'<svg class="d-tl" dir="ltr" viewBox="0 0 {W} {H}" role="img" aria-label="ציר זמן">' + ''.join(p) + '</svg>'


