def _D_NODE(x, y, t, c='#1b2d55', w=150):
    return (f'<rect x="{x - w / 2}" y="{y - 23}" width="{w}" height="46" rx="12" fill="{c}"/>'
            f'<text x="{x}" y="{y + 7}" font-size="19" font-weight="800" fill="#fff" text-anchor="middle" direction="rtl">{t}</text>')


def _D_LINK(x1, x2, y, t=''):
    lab = f'<text x="{(x1 + x2) / 2}" y="{y - 10}" font-size="16" font-weight="700" fill="#2a3858" text-anchor="middle" direction="rtl">{t}</text>' if t else ''
    return f'<line x1="{x1}" y1="{y}" x2="{x2}" y2="{y}" stroke="#5d6a86" stroke-width="3" stroke-dasharray="7 5"/>' + lab


def _D_TXT(x, y, t, fs=17, c='#2a3858', w=800):
    return f'<text x="{x}" y="{y}" font-size="{fs}" font-weight="{w}" fill="{c}" text-anchor="middle" direction="rtl">{t}</text>'


